const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  var furnaceCreek = ee.Geometry.Point([-116.8667, 36.4619]); // Furnace Creek Visitor's Center
  var date = '2013-06-30';
  var startDate = ee.Date(date);
  var endDate = startDate.advance(1, 'day'); // Next day to include the full day

  // 2. Data Acquisition - ERA5-Land Daily Aggregated (air temperature at 2m max)
  var era5 = ee.ImageCollection('ECMWF/ERA5_LAND/DAILY_AGGR')
    .filterDate(startDate, endDate)
    .filterBounds(furnaceCreek)
    .select('temperature_2m_max'); // Maximum air temperature at 2m (in Kelvin)

  // Check collection size
  var era5Size = era5.size().getInfo();
  print('ERA5-Land daily images for ' + date + ': ' + era5Size);

  if (era5Size === 0) {
    print('No ERA5-Land data found for the date.');
    print('<answer>C1</answer>');
    return;
  }

  // Get the image (should be one per day)
  var tempImage = era5.first();

  // 3. Processing: Get the temperature value at the point
  var result = tempImage.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: furnaceCreek,
    scale: 1000,
    maxPixels: 1e9,
  });

  var maxTempK = result.get('temperature_2m_max').getInfo();
  var count = result.get('temperature_2m_max_count').getInfo();

  print('Valid pixels at point: ' + count);
  if (count === 0) {
    print('No valid pixels after processing.');
    print('<answer>C2</answer>');
    return;
  }

  // Convert Kelvin to Celsius
  var maxTempC = maxTempK - 273.15;
  print('Maximum air temperature on ' + date + ': ' + maxTempC.toFixed(2) + ' °C');

  // 4. Validation & Final Answer
  // Check for invalid values (null, NaN, or unreasonable temperature for Earth's surface)
  if (maxTempC === null || isNaN(maxTempC) || maxTempC < -100 || maxTempC > 100) {
    print('Invalid temperature value: ' + maxTempC);
    print('<answer>C3</answer>');
  } else if (maxTempC > 58) {
    print('Temperature exceeded 58°C.');
    print('<answer>A</answer>');
  } else {
    print('Temperature did not exceed 58°C.');
    print('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
